WITH filtered_departments AS (SELECT * FROM departments WHERE budget > 2633000 OR dept_name = 'Legal'), Summary AS (SELECT CASE WHEN budget >= 3622000 THEN 'high' WHEN budget >= 1606000 THEN 'mid' ELSE 'low' END budget_bucket, dept_name, MAX(budget) max_budget, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) dept_name_values FROM filtered_departments GROUP BY CASE WHEN budget >= 3622000 THEN 'high' WHEN budget >= 1606000 THEN 'mid' ELSE 'low' END, dept_name) SELECT budget_bucket, dept_name, max_budget, dept_name_values FROM Summary WHERE max_budget < 1745000 ORDER BY budget_bucket ASC, dept_name ASC LIMIT 5;
